1	import fs from 'node:fs';
2	import path from 'node:path';
3	import crypto from 'node:crypto';
4	import { spawnSync } from 'node:child_process';
5	
6	const phase = path.dirname(new URL(import.meta.url).pathname.replace(/^\/(.:\/)/, '$1'));
7	const entry = path.resolve(phase, '../sources/package-0.7.7/bin/ai-writer.mjs');
8	const work = path.join(phase, 'work');
9	const [label, ...args] = process.argv.slice(2);
10	if (!/^[a-z0-9-]+$/.test(label ?? '')) throw new Error('A unique evidence label is required');
11	const output = path.join(phase, 'evidence', label);
12	fs.mkdirSync(output, { recursive: true });
13	const state = path.join(work, '.writer/state.json');
14	const hash = file => fs.existsSync(file) ? crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex') : null;
15	const start = new Date().toISOString();
16	const before = hash(state);
17	fs.writeFileSync(path.join(output, 'invocation.json'), JSON.stringify({ start, cwd: phase, executable: process.execPath, entry, args, state_sha256_before: before }, null, 2) + '\n', { flag: 'wx' });
18	const result = spawnSync(process.execPath, [entry, ...args], { cwd: phase, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024, windowsHide: true });
19	fs.writeFileSync(path.join(output, 'stdout.txt'), result.stdout ?? '', { flag: 'wx' });
20	fs.writeFileSync(path.join(output, 'stderr.txt'), result.stderr ?? '', { flag: 'wx' });
21	const metadata = { start, end: new Date().toISOString(), exit_code: result.status, signal: result.signal, spawn_error: result.error ? { code: result.error.code, message: result.error.message } : null, state_sha256_before: before, state_sha256_after: hash(state) };
22	fs.writeFileSync(path.join(output, 'result.json'), JSON.stringify(metadata, null, 2) + '\n', { flag: 'wx' });
23	process.stdout.write(JSON.stringify({ label, ...metadata }, null, 2) + '\n');
24	process.stdout.write(result.stdout ?? '');
25	process.stderr.write(result.stderr ?? '');
26	process.exitCode = result.status ?? 2;
